import{c as t,Q as s,j as a,m as o}from"./chunks/framework.CyZn50Me.js";const u=JSON.parse('{"title":"PRD-021 · Surface texture LOD strategy — sphere texture sharpness at mid-zoom on /mars, /moon, /earth","description":"","frontmatter":{},"headers":[],"relativePath":"prd/PRD-021.md","filePath":"prd/PRD-021.md"}'),r={name:"prd/PRD-021.md"};function i(n,e,l,d,c,h){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="prd-021-·-surface-texture-lod-strategy-—-sphere-texture-sharpness-at-mid-zoom-on-mars-moon-earth" tabindex="-1">PRD-021 · Surface texture LOD strategy — sphere texture sharpness at mid-zoom on <code>/mars</code>, <code>/moon</code>, <code>/earth</code> <a class="header-anchor" href="#prd-021-·-surface-texture-lod-strategy-—-sphere-texture-sharpness-at-mid-zoom-on-mars-moon-earth" aria-label="Permalink to &quot;PRD-021 · Surface texture LOD strategy — sphere texture sharpness at mid-zoom on `/mars`, `/moon`, `/earth`&quot;">​</a></h1><blockquote><p>Status · Draft Date · 2026-05-30 Owner · Marko Closes into · ADR-073 (technical decision), #284 (issue), eventual implementation slices Slice gate · Blocked by #283 Slice 6 — surface hotspots v2 / SurfaceScene refactor / flat ground patch must ship first</p></blockquote><blockquote><p><strong>Why this is a PRD.</strong> This isn&#39;t a UI-only tweak. We&#39;re committing to a new shape on the asset pipeline (per-region high-detail texture insets), a new descriptor on <code>SurfaceSite</code> (<code>inset_texture_path?: string</code>, <code>inset_zoom_threshold_ratio?: number</code>), a new precache tier for mobile (W6 / #276 coupling), and a runtime LOD-swap path in <code>SurfaceScene.svelte</code> (ADR-072) plus three callers (<code>/earth</code>, <code>/fly</code> cislunar, <code>/iss</code>, <code>/tiangong</code>). Those are spread across three subsystems and need a single owner doc.</p></blockquote><h2 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h2><p>Today every surface route renders its base body — Mars, Moon, Earth — with a single 2048×1024 equirectangular texture. At wide zoom that&#39;s fine. As the camera approaches the surface — <em>before</em> the flat ground-patch threshold trips (#283 Slice 6, Mars + Moon only) — the texels become larger than screen pixels and the sphere reads as visibly soft. NASA&#39;s interactive surface maps swap in higher-detail tiles continuously; we don&#39;t, and the softness is the first thing reviewers notice when comparing the two.</p><p>This PRD locks the strategy to fix that, scoped to:</p><ul><li>The 2K → 4K base swap on <code>/mars</code>, <code>/moon</code>, <code>/earth</code>, <code>/fly</code> cislunar, <code>/iss</code>, <code>/tiangong</code> whenever the body fills enough of the viewport.</li><li>Per-region high-detail texture insets at <code>SurfaceSite</code> lat/lon extents — Mars + Moon for v0.7, Earth gated on #285 (launchpads as surface sites).</li></ul><p><code>/explore</code> is out of scope (planet thumbnails never zoom large enough to soften).</p><h2 id="why-now" tabindex="-1">Why now <a class="header-anchor" href="#why-now" aria-label="Permalink to &quot;Why now&quot;">​</a></h2><p>Three signals converged:</p><ol><li><strong>#284 was filed as a forward-looking note when #283 was scoped</strong> — Marko flagged the sphere-softness symptom as a separate concern. The flat ground patch (#283 Slice 6) addresses <em>deep</em> zoom; this PRD addresses the <em>mid</em> zoom band that the flat patch doesn&#39;t cover.</li><li><strong>#283&#39;s SurfaceScene refactor (ADR-072) is the right insertion point</strong> — the sibling-agent slices currently in flight (1-2) standardise the sphere material assembly and give us one place to add the LOD-swap path that automatically benefits both <code>/mars</code> and <code>/moon</code>.</li><li><strong>#285 (launch sites on <code>/earth</code>) is on the roadmap for v0.8</strong> — when it lands, Earth picks up the SurfaceSite descriptor model. That&#39;s the right moment to add per-region Earth insets at no extra infrastructure cost. The base 2K → 4K swap on Earth ships first, decoupled.</li></ol><h2 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h2><p>Same audience as <code>/moon</code> and <code>/mars</code> today: educators, science writers, curious adults zooming in to inspect a specific landing site or surface feature. The visual contract is what the experience is selling — &quot;I can see Apollo 11 Tranquility Base in usable detail&quot; is meaningfully different from &quot;I can see a blurry equirectangular patch.&quot;</p><h2 id="goals-non-goals" tabindex="-1">Goals + non-goals <a class="header-anchor" href="#goals-non-goals" aria-label="Permalink to &quot;Goals + non-goals&quot;">​</a></h2><p><strong>Goals:</strong></p><ul><li><strong>Sphere texture stays subjectively sharp</strong> across the camera-distance range users actually traverse on <code>/moon</code> and <code>/mars</code>, with the threshold for &quot;approaching&quot; tunable per body via a single <code>inset_zoom_threshold_ratio</code> value.</li><li><strong>Mobile precache footprint stays within budget</strong> — the high tier carries 4K base textures (~12 MB extra across three bodies) + Layer A insets for the top-traffic regions; the mobile tier stays at 2K base + on-demand insets. Aligns with W6 / #276 deferred to v0.8.</li><li><strong>Asset provenance discipline survives unchanged</strong> — every new texture (4K base + per-region inset) carries a provenance entry per ADR-046 / ADR-047, fail-closed validated by <code>validate-data</code>.</li><li><strong>Three.js r128 compatibility maintained</strong> — the LOD-swap mechanism uses <code>material.map</code> reassignment + <code>needsUpdate = true</code>, which is r128-native. No r130+ APIs are taken on (ADR-001 pin).</li><li><strong>No regression in render-loop cost</strong> — the per-frame swap check is a single number comparison; the actual swap only fires on threshold cross.</li></ul><p><strong>Non-goals:</strong></p><ul><li>Tile streaming / quadtree (option 2 from the issue review). Right <em>eventual</em> answer if Orrery becomes a full interactive map, but its win is largest in exactly the zoom band the flat ground patch (#283 Slice 6) is taking over. Defer until there&#39;s signal it&#39;s needed; doesn&#39;t block any current user-facing problem.</li><li>8K base textures. Heavy GPU + bandwidth cost everywhere even when users orbit empty terrain.</li><li>Camera autopilot to regions. Threshold-based LOD swap is <em>responsive</em> to the user&#39;s zoom intent; it doesn&#39;t pull them toward regions automatically.</li><li>New surface-source pipelines beyond what existing fetches already provide. The fetch script will need to be re-pointed at a working high-res endpoint (Solar System Scope&#39;s <code>download/</code> URL started returning HTML some time after fetch-assets.ts was last run), but sourcing tiles, mosaicking, or polar-region special handling is out of scope.</li></ul><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><p>Locked by ADR-073. Summary:</p><h3 id="layer-a-—-per-region-high-detail-texture-insets" tabindex="-1">Layer A — per-region high-detail texture insets <a class="header-anchor" href="#layer-a-—-per-region-high-detail-texture-insets" aria-label="Permalink to &quot;Layer A — per-region high-detail texture insets&quot;">​</a></h3><p>For each <code>SurfaceSite</code> / region with user-attention, generate a higher-resolution sphere-projected texture inset at the region&#39;s lat/lon extent. The inset overlays the base sphere material in a bounded UV rectangle around the region when:</p><ul><li><code>camR / body_radius &lt;= inset_zoom_threshold_ratio</code> (default 1.5, tunable per region)</li><li>The camera line-of-sight intersects the region&#39;s <code>region_bounds</code> (already on the SurfaceSite schema per ADR-061)</li></ul><p>When either gate releases, the inset is unloaded; the base sphere material takes back over.</p><p><strong>Descriptor extension on SurfaceSite:</strong></p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;apollo-11&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;region_bounds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},                                        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ADR-061</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;inset_texture_path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;textures/insets/moon/apollo-11/2k.jpg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// NEW (PRD-021)</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;inset_zoom_threshold_ratio&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              // NEW, optional</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="layer-b-—-base-2k-→-4k-swap" tabindex="-1">Layer B — base 2K → 4K swap <a class="header-anchor" href="#layer-b-—-base-2k-→-4k-swap" aria-label="Permalink to &quot;Layer B — base 2K → 4K swap&quot;">​</a></h3><p>For bodies-of-no-interest zoom (no SurfaceSite in line-of-sight), the base sphere material swaps to a 4K texture when <code>camR / body_radius</code> is below the swap threshold (default 2.5 for /earth, 3.0 for /mars and /moon — tuned per body&#39;s typical camera range).</p><p><strong>Asset shape:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static/textures/2k_&lt;body&gt;_daymap.jpg          # existing, default base</span></span>\n<span class="line"><span>static/textures/4k_&lt;body&gt;_daymap.jpg          # NEW, swap-in target</span></span></code></pre></div><p>Provenance entry per file. License continues to be CC-BY-4.0 attributed to Solar System Scope (or equivalent — the fetch script picks the source).</p><h3 id="both-layers-compose" tabindex="-1">Both layers compose <a class="header-anchor" href="#both-layers-compose" aria-label="Permalink to &quot;Both layers compose&quot;">​</a></h3><p>A user zooming toward Apollo 11 sees: 2K base at wide → 4K base on closing approach (Layer B threshold) → Layer A inset on top of the 4K base once region line-of-sight + threshold both fire. When they pull back, the sequence reverses cleanly.</p><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><ul><li><strong>Mobile precache budget</strong> — current workbox precache is at 754 MiB (per #95 review). Layer B 4K bases add ~12 MB; Layer A insets are bounded by region count × inset size (target: ~500 KB per inset, ~10-20 regions per body). All ships within budget.</li><li><strong>PWA install size on mobile</strong> — high tier carries everything; mobile tier carries 2K base + nearest-region inset only. SW precache tier strategy ships as part of W6 (#276).</li><li><strong>Three.js r128</strong> — <code>material.map</code> reassignment + <code>needsUpdate = true</code> is r128-native. No <code>MeshStandardMaterial.uniforms</code> shader-side LOD, no quadtree, no <code>CubeTextureLoader</code> tricks.</li><li><strong>Provenance fail-closed</strong> — every new texture path requires an entry in <code>image-provenance.json</code> per ADR-047. <code>validate-data</code> enforces.</li><li><strong>No render-path regression</strong> — per-frame swap check stays cheap (single comparison + bounded threshold-cross writes). Test gate: <code>dispose-leak.test.ts</code> extended to verify both 2K and 4K textures dispose cleanly on route teardown.</li></ul><h2 id="scope-by-body" tabindex="-1">Scope by body <a class="header-anchor" href="#scope-by-body" aria-label="Permalink to &quot;Scope by body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Body</th><th>Layer B base swap</th><th>Layer A insets</th><th>Notes</th></tr></thead><tbody><tr><td><code>/mars</code> (and <code>SurfaceScene</code> consumer)</td><td>Yes — 2K → 4K</td><td>Yes for rover sites + Apollo/Artemis regions</td><td>Primary case; integrates with #283 region work directly</td></tr><tr><td><code>/moon</code> (and <code>SurfaceScene</code> consumer)</td><td>Yes — 2K → 4K</td><td>Yes for Apollo + Luna + Chang&#39;e + future lunar-base regions</td><td>Same as Mars; the threshold ratios differ because tidal lock means the user usually approaches the near-side hemisphere</td></tr><tr><td><code>/earth</code></td><td>Yes — 2K → 4K</td><td><strong>Gated on #285</strong></td><td>Launch sites land first; insets follow. Base swap ships now because the existing /earth scene already invites close inspection of LEO satellite altitudes</td></tr><tr><td><code>/fly</code> cislunar (Earth + Moon meshes)</td><td>Yes — 2K → 4K</td><td>Inherits the Moon SurfaceSite insets via Layer A automatically; Earth inherits via #285</td><td>The cislunar scene&#39;s Earth and Moon meshes use the same texture URLs the surface routes do; pointing them at the LOD-swap path is one parameter change in <code>buildCislunarScene</code>&#39;s options</td></tr><tr><td><code>/iss</code>, <code>/tiangong</code> (Earth backdrop)</td><td>Yes — 2K → 4K, <strong>only if camera approaches Earth</strong></td><td>Earth via #285</td><td>The station scenes default to ISS-local coords; Earth is far context. Probably won&#39;t trip the swap threshold often, but the mechanism is shared</td></tr><tr><td><code>/explore</code></td><td>No</td><td>No</td><td>Planet thumbnails stay at 2K; never zoom close enough</td></tr></tbody></table><h2 id="success-criteria" tabindex="-1">Success criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success criteria&quot;">​</a></h2><ul><li><strong>Visual</strong>: side-by-side screenshots at the threshold-crossing camera distance for /mars, /moon, /earth show a clearly sharper sphere texture without artefacts (no seam at the swap boundary, no flicker, no flash to lower res mid-swap).</li><li><strong>Per-region insets</strong>: Apollo 11 / Curiosity Bradbury Landing / launchpad LC-39A (when #285 lands) read at meaningfully higher detail than the rest of the sphere around them, with the inset edge invisible (alpha-feathered or seam-aligned).</li><li><strong>Performance</strong>: animation framerate ≥ 55 fps on a 2020-era mid-tier laptop GPU during a sweep that crosses both Layer B and Layer A thresholds. Memory ceiling: <code>renderer.info.memory.textures ≤ 12</code> during normal usage on <code>/mars</code> or <code>/moon</code>.</li><li><strong>Mobile</strong>: PWA install size on the mobile tier stays within current budget (no W6 / #276 acceleration needed <em>for this work</em>). Layer A inset on-demand load on mobile completes in ≤ 2 s on a 4G connection.</li><li><strong>Provenance gates</strong>: <code>validate-data</code> continues green; every new texture has a complete provenance entry; the per-region inset cross-reference (SurfaceSite.inset_texture_path → on-disk file) is validated.</li><li><strong>e2e</strong>: a smoke spec asserts the LOD swap fires + unswaps + cleans up (<code>renderer.info.memory.textures</code> snapshot before / after) for at least one body per workflow.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Real-time satellite imagery overlay (e.g. ISS view from current orbital position). Different surface, different latency budget. Future work.</li><li>Adjustments to the SurfaceSite line-of-sight gate computation beyond what ADR-061 already specified for <code>region_bounds</code>.</li><li>Generative super-resolution (e.g. an upscaling model in the asset pipeline). Compromises provenance; we&#39;d be attributing pixels we generated to the source agency.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><strong>#283</strong> — surface hotspots v2 / SurfaceScene refactor / flat ground patch (hard prerequisite, Slice 6)</li><li><strong>#284</strong> — issue this PRD closes into; chosen approach is option 3 (per-region insets) + option 1 sub-case (2K → 4K base swap)</li><li><strong>#285</strong> — launch sites on <code>/earth</code> (gates Layer A on Earth)</li><li><strong>#276</strong> — W6 responsive image variants + mobile-tier SW precache (mobile-tier coupling)</li><li><strong>#124</strong> — 3D marker fidelity (becomes more relevant as camera gets closer to surface)</li><li><strong>ADR-001</strong> — Three.js r128 pin (constrains the swap mechanism to r128-native APIs)</li><li><strong>ADR-046 / ADR-047</strong> — provenance manifest (covers new inset + 4K base entries)</li><li><strong>ADR-061</strong> — <code>region_bounds</code> on <code>SurfaceSite</code> (Layer A line-of-sight check)</li><li><strong>ADR-072</strong> — shared <code>SurfaceScene.svelte</code> (Layer A + Layer B integration point)</li><li><strong>ADR-073</strong> — technical decision lock for this PRD</li></ul>',43)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
